// Generate bounded MCP regression inputs; generated files contain private samples.
// Never include .test-output in a distributable archive.
import fs from 'node:fs/promises';
import {build} from 'esbuild';
import {zlibSync} from 'fflate';
const input=process.argv[2];if(!input)throw new Error('Pass a local scene JSON generated by test:samples');
const scene=JSON.parse(await fs.readFile(input,'utf8'));
const packed=Buffer.from(zlibSync(new TextEncoder().encode(JSON.stringify(scene)))).toString('base64');
const chunks=packed.match(/.{1,42000}/g);
await build({stdin:{contents:"export {unzlibSync,strFromU8} from 'fflate';",resolveDir:process.cwd(),loader:'js'},bundle:true,format:'iife',globalName:'Compression',minify:true,outfile:'.test-output/compression.js'});
await build({stdin:{contents:(await fs.readFile('src/builder.ts','utf8')).replace(/(\w+)\.setPluginData\(/g,'__testMetadata($1,').replace(/await new Promise\(r=>setTimeout\(r,0\)\)/g,'void 0'),resolveDir:process.cwd()+'/src',loader:'ts'},bundle:true,format:'iife',globalName:'Importer',minify:true,outfile:'.test-output/figma-builder.js'});
const decoder=`function decode64(s){const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';const out=[];let bits=0,value=0;for(const c of s){if(c==='=')break;value=(value<<6)|alphabet.indexOf(c);bits+=6;if(bits>=8){bits-=8;out.push((value>>bits)&255);}}return new Uint8Array(out);}`;
const code=`const metadata={};function __testMetadata(node,key,value){(metadata[node.id]??={})[key]=value;}`+
 await fs.readFile('.test-output/compression.js','utf8')+await fs.readFile('.test-output/figma-builder.js','utf8')+decoder;
await fs.writeFile('.test-output/figma-stage.json',JSON.stringify({chunks,code}));
console.log(JSON.stringify({chunks:chunks.length,characters:packed.length,builderCharacters:code.length}));
